package id.tracive.sdk.cache

/**
 * The 256-bit key the cache's records are encrypted with, and where it lives.
 *
 * This is the one part of the cache that genuinely needs the platform. The cipher itself is common
 * Kotlin (see `AesGcm.kt`), but key *material* must be generated by a real entropy source and held
 * somewhere the operating system protects — the Android Keystore, or the iOS Keychain with a
 * Secure-Enclave-backed protection class where the device offers one. Never a file, never
 * `SharedPreferences`, never `UserDefaults`.
 *
 * Generation is the store's job rather than the cache's, deliberately: common Kotlin has no
 * cryptographically secure random number generator (`kotlin.random.Random` is not one), and a key
 * generated from a weak source is worse than no encryption because it looks like encryption.
 * Delegating [createKey] to the platform puts key generation where the entropy actually is.
 *
 * ### The contract implementations must honour
 *
 * 1. [createKey] returns a **fresh** 32-byte key from a cryptographically secure source, persists
 *    it under the returned id, and never returns the same key twice.
 * 2. [loadKey] returns exactly the bytes stored under that id, or null if it is gone — after an OS
 *    keystore reset, a device restore, or a biometric enrolment change that invalidated the key.
 *    Null is expected and handled: the cache discards its rows and starts over with a new key.
 * 3. Keys are never logged, never copied to disk in the clear, and never leave the device.
 *
 * A returned key's bytes are read once, at cache open, and the cache does not retain the
 * [CacheDataKey] wrapper afterwards.
 */
interface CacheDataKeyStore {

  /**
   * Generates and persists a new data key.
   *
   * Called when the cache has no key yet, when the schema version changed, and when [loadKey] could
   * not return the previous one. Each call must produce fresh key material.
   */
  suspend fun createKey(): CacheDataKey

  /** The key stored under [id], or null if it no longer exists. */
  suspend fun loadKey(id: String): CacheDataKey?

  /**
   * Deletes the key stored under [id]. Called when the cache abandons a generation of records.
   *
   * Must not throw when the id is unknown — deleting a key that is already gone is the desired end
   * state, not an error.
   */
  suspend fun deleteKey(id: String)
}

/**
 * One data key: an id the cache stores in cleartext next to its rows, and the key bytes themselves.
 *
 * Not a `data class`: the generated `toString` would print the key, and the generated `equals`
 * would compare it in variable time.
 */
class CacheDataKey(
  /**
   * Stable identifier for this key inside the platform key store. Safe to store in the database.
   */
  val id: String,
  bytes: ByteArray,
) {

  /** The raw 256-bit key. Copied on the way in and on the way out, so no caller can mutate it. */
  val bytes: ByteArray
    get() = storedBytes.copyOf()

  private val storedBytes: ByteArray = bytes.copyOf()

  init {
    require(id.isNotBlank()) { "A CacheDataKey needs an id." }
    require(storedBytes.size == KEY_SIZE) { "A Tracive cache data key must be $KEY_SIZE bytes." }
  }

  /** Redacted. A key that reaches a log line is a key that has to be rotated. */
  override fun toString(): String = "CacheDataKey(id=$id, bytes=redacted)"

  companion object {
    /** Data key length in bytes. AES-256. */
    const val KEY_SIZE: Int = 32
  }
}

/**
 * A [CacheDataKeyStore] that holds one caller-supplied key in memory for the life of the process.
 *
 * For tests, and for pairing with [InMemoryCheckCache] where nothing is written to disk in the
 * first place.
 *
 * **Never pair this with a persistent record store.** The cache's nonces are a counter that resets
 * whenever the database is recreated; that is safe only because a new database also gets a new key.
 * A store that hands out the same key to a fresh database breaks the one assumption AES-GCM cannot
 * survive being wrong about — a repeated nonce under a repeated key reveals the authentication
 * subkey for every record written with it.
 */
class InMemoryCacheDataKeyStore(key: ByteArray) : CacheDataKeyStore {

  private var current: CacheDataKey? = null
  private val keyBytes: ByteArray = key.copyOf()
  private var generation: Int = 0

  init {
    require(keyBytes.size == CacheDataKey.KEY_SIZE) {
      "An in-memory cache data key must be ${CacheDataKey.KEY_SIZE} bytes."
    }
  }

  override suspend fun createKey(): CacheDataKey {
    generation += 1
    return CacheDataKey("in-memory-$generation", keyBytes).also { current = it }
  }

  override suspend fun loadKey(id: String): CacheDataKey? = current?.takeIf { it.id == id }

  override suspend fun deleteKey(id: String) {
    if (current?.id == id) current = null
  }
}
